CharacterizationRule.StructuralMatch:
FunctionCall fc:
    function is [Function:
        name == "FindClass"
        and enclosingClass.supers contains [Class:
            name == "JNIEnv_"
        ]
    ]
    and arguments[0] is [Expression e:]

FunctionCall fc:
    function is [Function:
        name == "FindClass"
        and enclosingClass.supers contains [Class:
            name == "JNIEnv_"
        ]
    ]
    and arguments[0] is [Expression e:]

