g_strlcat(dest, src, dlen) {
    //BufferRead(src, 0, min(src.$strlen, dlen - dest.$strlen - 1))
    BufferWrite(dest, dest.$strlen, min(src.$strlen + 1, dlen - dest.$strlen))
    Ensures(dest.$strlen' == min(dest.$strlen + src.$strlen, dlen - 1))
    Ensures(dest.$size' == dest.$size)
    Ensures(dest.$offset' == dest.$offset)
    Ensures(return == dest.$strlen + src.$strlen)
}

                g_strlcpy(dest, src, dlen) {
                    //BufferRead(src, 0, min(src.$strlen, dlen))
                    //BufferRead with strlen produces false negatives
                    BufferWrite(dest, 0, min(src.$strlen + 1, dlen))
                    Ensures(dest.$strlen' == min(src.$strlen, dlen - 1))
                    Ensures(dest.$size' == dest.$size)
                    Ensures(dest.$offset' == dest.$offset)
                    Ensures(return == src.$strlen)

		    controlflow:
			Copy(in=dest, out=return)
                }

g_strndup(s, n) {
