{g_strstr, g_strrstr} (haystack, needle) {
    //BufferRead(haystack, 0, haystack.$strlen)
    //BufferRead(needle, 0, needle.$strlen)
    Ensures(return.$strlen <= haystack.$strlen)
    Ensures(return.$strlen >= needle.$strlen)
    Ensures(return.$size == haystack.$size)
    Ensures(return.$offset < haystack.$offset + haystack.$strlen - needle.$strlen)
    Ensures(return.$offset >= haystack.$offset)
}

{g_strstr_len,g_strrstr_len}(haystack, len, needle) {
    //BufferRead(haystack, 0, min(haystack.$strlen, len))
    BufferRead(haystack, 0, len)
    //BufferRead(needle, 0, needle.$strlen)
    Ensures(return.$strlen <= min(haystack.$strlen, len))
    Ensures(return.$strlen >= needle.$strlen)
    Ensures(return.$size == haystack.$size)
    Ensures(return.$offset < haystack.$offset + min(haystack.$strlen, len) - needle.$strlen)
    Ensures(return.$offset >= haystack.$offset)
}

