g_unicode_canonical_ordering(str, len) {
    //BufferRead(str, 0, min(str.$strlen, len)*4)
    BufferWrite(str, 0, min(str.$strlen, len)*4)
    Ensures(str.$strlen' == str.$strlen)
    Ensures(str.$size' == str.$size)
    Ensures(str.$offset' == str.$offset)
}

g_utf8_get_char_validated(str, len) {
    BufferRead(str, 0, ((len < 0) ? 4 : len))
}

g_utf8_pointer_to_offset(str, pos) {
    BufferRead(str, 0, pos - str)
    Ensures(return <= (pos - str))
    Ensures(return >= (pos - str)/4)
}

g_utf8_strlen(str, max) {
    //BufferRead(str, 0, ((max < 0) ? str.$strlen : min(str.$strlen, max))*4)
    Ensures(return == ((max < 0) ? str.$strlen : min(str.$strlen, max)))
}

{g_utf8_strrchr, g_utf8_strchr} (str, n, ch) {
    //BufferRead(str, 0, ((n < 0) ? str.$strlen : min(str.$strlen, n)))
    BufferRead(str, 0, n)
    Ensures(return.$strlen <= ((n < 0) ? str.$strlen : n))
    Ensures(return.$strlen >= 1)
    Ensures(return.$offset >= str.$offset + max(str.$strlen - n, 0))
    Ensures(return.$offset <= str.$offset + str.$strlen)
