state nofree (start);
state free : "pointer.freed";
state used (error) : "pointer.usedafterfreed";
var p;
pattern ignore_pattern {
    $func_free(p)
}
 pattern bad_pattern {
    *p |
    #any_function(..., p, ...) |
    #return(p)
}
nofree -> free { $func_free(p) }
free -> nofree { p = ? | #any_function(..., &p, ...) }
free -> free { pattern ignore_pattern }
free -> used { pattern bad_pattern }

state nofree (start);
state free : "pointer.freed";
state safe;
state doublefree (error) : "pointer.doublefreed";
var p;
nofree -> free { $free(p) }
free -> safe { p = ? | #any_function(..., &p, ...) }
free -> doublefree { $free(p) }

state start (start);
state allocated : "memory.allocated";
state safe;
state leak (error) : "memory.leaked";
var m;
start -> allocated { m = $allocate(...) }
allocated -> safe { $free(..., m, ...) | #ifblock(m, null, true) | @Escape(m -> escapeArg) | #escape(m) }
allocated -> allocated { @Copy(m -> in, m <- out) }
allocated -> leak { #end_scope(m) }

state start (start);
state allocated : "nullreturn.mayReturnNull";
state checked;
state used (error) : "nullreturn.used";
var p;
start -> allocated { p = $allocate(...) }
/* free(null) is ok */
allocated -> allocated { #return(p) | $free(...,p,...) }
allocated -> checked { #compare(p, 0) | #end_scope(p) }
allocated -> used { p }

